void cmp_connection_break ( struct cmp_connection * c ) { int err ; if ( ! c -> connected ) { mutex_unlock ( & c -> mutex ) ; return ; } err = pcr_modify ( c , pcr_break_modify , NULL , SUCCEED_ON_BUS_RESET ) ; if ( err < 0 ) { cmp_error ( c , "plug is still connected\n" ) ; } c -> connected = false ; mutex_unlock ( & c -> mutex ) ; } 